import requests, json, numpy as np, re
from collections import Counter
import matplotlib.pyplot as plt
UA={'User-Agent':'Mozilla/5.0'}

# ---------- A. HPA consensus tissue nTPM for human ACCSL ----------
cols=('g,eg,rnatsm,'
      't_RNA_testis,t_RNA_liver,t_RNA_brain,t_RNA_kidney,t_RNA_heart_muscle,t_RNA_skeletal_muscle,'
      't_RNA_lung,t_RNA_pancreas,t_RNA_spleen,t_RNA_thyroid_gland,t_RNA_epididymis,t_RNA_seminal_vesicle,'
      't_RNA_prostate,t_RNA_ovary,t_RNA_placenta,t_RNA_bone_marrow,t_RNA_colon,t_RNA_stomach_1')
try:
    r=requests.get(f'https://www.proteinatlas.org/api/search_download.php?search=ACCSL&format=json&compress=no&columns={cols}',
                   headers=UA,timeout=60)
    js=r.json()
    print('HPA status',r.status_code,'records',len(js))
    for rec in js:
        if rec.get('Gene','').upper()=='ACCSL':
            vals={k:v for k,v in rec.items() if k.startswith('Tissue RNA')}
            print('  Gene',rec.get('Gene'),'Ensembl',rec.get('Ensembl'),'| tissue specificity:',rec.get('RNA tissue specificity'))
            nz=[(k.replace('Tissue RNA - ','').replace(' [nTPM]',''),v) for k,v in vals.items()]
            for k,v in nz: print(f'    {k:22s} nTPM = {v}')
except Exception as e:
    print('HPA tissue query failed:',type(e).__name__,e)

# ---------- B. gnomAD constraint for ACCSL ----------
Q = """
query($g:String!){
  gene(gene_symbol:$g, reference_genome:GRCh38){
    gene_id symbol
    gnomad_constraint{ pLI oe_lof oe_lof_lower oe_lof_upper obs_lof exp_lof mis_z syn_z }
  }
}"""
try:
    r=requests.post('https://gnomad.broadinstitute.org/api',
                    json={'query':Q,'variables':{'g':'ACCSL'}},
                    headers={**UA,'Content-Type':'application/json'},timeout=90)
    print('\ngnomAD status',r.status_code)
    d=r.json()
    g=(d.get('data') or {}).get('gene')
    if g:
        print('  gene',g['symbol'],g['gene_id'])
        c=g.get('gnomad_constraint')
        if c:
            for k,v in c.items(): print(f'    {k}: {v}')
        else: print('    no constraint record')
    else:
        print('  response:',json.dumps(d)[:400])
except Exception as e:
    print('gnomAD query failed:',type(e).__name__,e)

# ---------- C. composition of the Accsl N-terminal extension ----------
def fasta_one(acc):
    t=requests.get(f'https://rest.uniprot.org/uniprotkb/{acc}.fasta',headers=UA,timeout=60).text
    return ''.join(l.strip() for l in t.split('\n')[1:])
rat=fasta_one('D3ZUW2'); hum=fasta_one('Q4AC99')
ext_r=rat[:158]; core_r=rat[158:558]
def comp(s):
    c=Counter(s); n=len(s)
    dis=sum(c[a] for a in 'PESTQKAGR')/n      # disorder-promoting set
    ord_=sum(c[a] for a in 'WFYILVCMN')/n     # order-promoting set
    return dis,ord_,c
dr,orr,cr=comp(ext_r); dc,oc,cc_=comp(core_r)
print(f'\nrat Accsl 1-158 (no ACS counterpart): {len(ext_r)} aa  disorder-promoting PESTQKAGR {100*dr:.1f}%  order-promoting WFYILVCMN {100*orr:.1f}%')
print(f'rat Accsl 159-558 (ACS-aligned core): {len(core_r)} aa  disorder-promoting {100*dc:.1f}%  order-promoting {100*oc:.1f}%')
print('  most frequent residues in 1-158:', cr.most_common(6))
# identity of the extension vs human, compared with the core
def pid(a,b):
    n=min(len(a),len(b)); return 100*sum(1 for i in range(n) if a[i]==b[i])/n
print(f'\nhuman Q4AC99 length {len(hum)}; rat {len(rat)}')
print('  (ungapped positional identity is only indicative here)')

# ---------- D. figure: HPA tissue nTPM ----------
try:
    labels=[k for k,v in nz]; vv=[float(v) if v not in (None,'','NA') else 0.0 for k,v in nz]
    order=np.argsort(vv)[::-1]
    fig,ax=plt.subplots(figsize=(9,4))
    ax.bar([labels[i] for i in order],[vv[i] for i in order],color='#4c72b0')
    ax.axhline(1.0,ls='--',lw=0.9,color='k')
    ax.annotate('HPA detection threshold, nTPM = 1',(len(labels)-1,1.05),ha='right',fontsize=8)
    ax.set_ylabel('consensus tissue nTPM'); ax.set_ylim(0,max(2.0,max(vv)*1.2))
    plt.xticks(rotation=55,ha='right',fontsize=8)
    ax.set_title('Human ACCSL RNA is below the detection threshold in every tissue sampled by HPA',fontsize=10,loc='left')
    plt.tight_layout(); plt.show()
except Exception as e:
    print('figure skipped:',type(e).__name__,e)
